USE academia_cursos;

--
-- Create table `tipos_area`
--
CREATE TABLE tipos_area (
  id_tipo_area int(11) NOT NULL AUTO_INCREMENT,
  nombre varchar(50) NOT NULL,
  PRIMARY KEY (id_tipo_area)
)
ENGINE = INNODB,
AUTO_INCREMENT = 11,
AVG_ROW_LENGTH = 16384,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `sp_tipos_area_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_tipo_area,
    nombre
  FROM tipos_area
  WHERE id_tipo_area = p_id;
END
$$

--
-- Create procedure `sp_tipos_area_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_listar ()
BEGIN
  SELECT
    id_tipo_area,
    nombre
  FROM tipos_area
  ORDER BY nombre;
END
$$

--
-- Create procedure `sp_tipos_area_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_eliminar (IN p_id int)
BEGIN
  DELETE
    FROM tipos_area
  WHERE id_tipo_area = p_id;
END
$$

--
-- Create procedure `sp_tipos_area_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_crear (IN p_nombre varchar(50))
BEGIN
  INSERT INTO tipos_area (nombre)
    VALUES (p_nombre);
END
$$

--
-- Create procedure `sp_tipos_area_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    id_tipo_area,
    nombre
  FROM tipos_area
  WHERE nombre LIKE CONCAT('%', p_term, '%')
  ORDER BY nombre;
END
$$

--
-- Create procedure `sp_tipos_area_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_area_actualizar (IN p_id int, IN p_nombre varchar(50))
BEGIN
  UPDATE tipos_area
  SET nombre = p_nombre
  WHERE id_tipo_area = p_id;
END
$$

