    id_tipo_area,
    nombre
  FROM areas
  WHERE id_area = p_id;
END
$$

--
-- Create procedure `sp_areas_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_listar ()
BEGIN
  SELECT
    a.id_area,
    a.nombre,
    ta.nombre AS tipo_area
  FROM areas a
    JOIN tipos_area ta
      ON a.id_tipo_area = ta.id_tipo_area
  ORDER BY a.nombre;
END
$$

--
-- Create procedure `sp_areas_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_eliminar (IN p_id int)
