  WHERE id_area = p_id;
END
$$

--
-- Create procedure `sp_areas_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_crear (IN p_id_tipo_area int, IN p_nombre varchar(100))
BEGIN
  INSERT INTO areas (id_tipo_area, nombre)
    VALUES (p_id_tipo_area, p_nombre);
END
$$

--
-- Create procedure `sp_areas_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    a.id_area,
    a.nombre,
    ta.nombre AS tipo_area
  FROM areas a
    JOIN tipos_area ta
      ON a.id_tipo_area = ta.id_tipo_area
  WHERE a.nombre LIKE CONCAT('%', p_term, '%')
  OR ta.nombre LIKE CONCAT('%', p_term, '%')
  ORDER BY a.nombre;
END
$$

--
-- Create procedure `sp_areas_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_actualizar (IN p_id_area int, IN p_id_tipo_area int, IN p_nombre varchar(100))
