--
-- Create procedure `sp_sub_areas_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_sub_areas_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    sa.id_sub_area,
    sa.descripcion,
    sa.numero_sub_area,
    sa.capacidad_maxima,
    a.nombre AS area_nombre
  FROM sub_areas sa
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE sa.descripcion LIKE CONCAT('%', p_term, '%')
  OR sa.numero_sub_area LIKE CONCAT('%', p_term, '%')
  OR a.nombre LIKE CONCAT('%', p_term, '%')
  ORDER BY a.nombre, sa.descripcion;
END
$$

