-- Create index `email_UNIQUE` on table `usuarios`
--
ALTER TABLE usuarios
ADD UNIQUE INDEX email_UNIQUE (email);

--
-- Create index `fk_usuarios_roles_idx` on table `usuarios`
--
ALTER TABLE usuarios
ADD INDEX fk_usuarios_roles_idx (id_rol);

--
-- Create foreign key
--
ALTER TABLE usuarios
ADD CONSTRAINT fk_usuarios_roles FOREIGN KEY (id_rol)
REFERENCES roles (id_rol) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_usuarios_verificar_codigo_2fa`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_verificar_codigo_2fa (IN p_id_usuario int,
IN p_codigo varchar(10))
BEGIN
  SELECT
    id_usuario
  FROM usuarios
  WHERE id_usuario = p_id_usuario
  AND auth_2fa_code = p_codigo
  AND auth_2fa_expiry > NOW();
END
$$

--
-- Create procedure `sp_usuarios_obtener_por_nombre`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_obtener_por_nombre (IN p_nombre_usuario varchar(50))
BEGIN
  SELECT
    id_usuario,
    id_rol,
    nombre_usuario,
    password_hash,
    email,
    nombre_completo,
    activo
  FROM usuarios
  WHERE nombre_usuario = p_nombre_usuario
  AND activo = 1;
END
$$

--
-- Create procedure `sp_usuarios_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_obtener_por_id (IN p_id_usuario int)
BEGIN
  SELECT
    u.id_usuario,
    u.id_rol,
    r.nombre_rol,
    u.nombre_usuario,
    u.email,
    u.nombre_completo,
    u.activo,
    u.fecha_creacion
  FROM usuarios u
    JOIN roles r
      ON u.id_rol = r.id_rol
  WHERE u.id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_listar ()
BEGIN
  SELECT
    u.id_usuario,
    u.id_rol,
    r.nombre_rol,
    u.nombre_usuario,
    u.email,
    u.nombre_completo,
    u.activo
  FROM usuarios u
    JOIN roles r
      ON u.id_rol = r.id_rol
  ORDER BY u.nombre_completo;
END
$$

--
-- Create procedure `sp_usuarios_guardar_codigo_2fa`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_guardar_codigo_2fa (IN p_id_usuario int,
IN p_codigo varchar(10),
IN p_expiracion datetime)
BEGIN
  UPDATE usuarios
  SET auth_2fa_code = p_codigo,
      auth_2fa_expiry = p_expiracion
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_eliminar (IN p_id_usuario int)
BEGIN
  UPDATE usuarios
  SET activo = 0
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_crear (IN p_id_rol int,
IN p_nombre_usuario varchar(50),
IN p_password_hash varchar(255),
IN p_email varchar(100),
IN p_nombre_completo varchar(150))
BEGIN
  INSERT INTO usuarios (id_rol, nombre_usuario, password_hash, email, nombre_completo, activo)
    VALUES (p_id_rol, p_nombre_usuario, p_password_hash, p_email, p_nombre_completo, 1);
END
$$

--
-- Create procedure `sp_usuarios_cambiar_password`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_cambiar_password (IN p_id_usuario int,
IN p_password_hash varchar(255))
BEGIN
  UPDATE usuarios
  SET password_hash = p_password_hash
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_actualizar (IN p_id_usuario int,
IN p_id_rol int,
IN p_nombre_usuario varchar(50),
IN p_email varchar(100),
IN p_nombre_completo varchar(150),
IN p_activo tinyint(1))
BEGIN
  UPDATE usuarios
  SET id_rol = p_id_rol,
      nombre_usuario = p_nombre_usuario,
      email = p_email,
      nombre_completo = p_nombre_completo,
      activo = p_activo
  WHERE id_usuario = p_id_usuario;
END
$$

DELIMITER ;

--
-- Create table `tipos_documento`
--
CREATE TABLE tipos_documento (
  id_tipo_documento int(11) NOT NULL AUTO_INCREMENT,
  descripcion varchar(50) NOT NULL,
  longitud int(11) DEFAULT NULL,
  codigo_sunat varchar(2) DEFAULT NULL,
  PRIMARY KEY (id_tipo_documento)
)
ENGINE = INNODB,
AUTO_INCREMENT = 7,
AVG_ROW_LENGTH = 4096,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `sp_tipos_documento_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_tipo_documento,
    descripcion,
    longitud,
    codigo_sunat
  FROM tipos_documento
  WHERE id_tipo_documento = p_id;
END
$$

--
-- Create procedure `sp_tipos_documento_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_listar ()
BEGIN
  SELECT
    id_tipo_documento,
    descripcion,
    longitud,
    codigo_sunat
  FROM tipos_documento
  ORDER BY descripcion;
END
$$

--
-- Create procedure `sp_tipos_documento_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_eliminar (IN p_id int)
BEGIN
  DELETE
    FROM tipos_documento
  WHERE id_tipo_documento = p_id;
END
$$

--
-- Create procedure `sp_tipos_documento_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_crear (IN p_descripcion varchar(50),
IN p_longitud int,
IN p_codigo_sunat varchar(2))
BEGIN
  INSERT INTO tipos_documento (descripcion, longitud, codigo_sunat)
    VALUES (p_descripcion, p_longitud, p_codigo_sunat);
END
$$

--
-- Create procedure `sp_tipos_documento_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    id_tipo_documento,
    descripcion,
    longitud,
    codigo_sunat
  FROM tipos_documento
  WHERE descripcion LIKE CONCAT('%', p_term, '%')
  OR codigo_sunat LIKE CONCAT('%', p_term, '%')
  ORDER BY descripcion;
END
$$

--
-- Create procedure `sp_tipos_documento_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_actualizar (IN p_id int,
IN p_descripcion varchar(50),
IN p_longitud int,
IN p_codigo_sunat varchar(2))
BEGIN
  UPDATE tipos_documento
  SET descripcion = p_descripcion,
      longitud = p_longitud,
      codigo_sunat = p_codigo_sunat
  WHERE id_tipo_documento = p_id;
END
$$

DELIMITER ;

--
-- Create table `profesores`
--
CREATE TABLE profesores (
  id_profesor int(11) NOT NULL AUTO_INCREMENT,
  id_tipo_documento int(11) NOT NULL,
  numero_documento varchar(20) NOT NULL,
  nombres varchar(100) NOT NULL,
  apellidos varchar(100) NOT NULL,
  email varchar(100) DEFAULT NULL,
  telefono varchar(20) DEFAULT NULL,
  especialidad varchar(255) DEFAULT NULL,
  PRIMARY KEY (id_profesor)
)
ENGINE = INNODB,
AUTO_INCREMENT = 5,
AVG_ROW_LENGTH = 4096,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `documento_UNIQUE` on table `profesores`
--
ALTER TABLE profesores
ADD UNIQUE INDEX documento_UNIQUE (id_tipo_documento, numero_documento);

--
-- Create index `fk_profesores_tipos_documento_idx` on table `profesores`
--
ALTER TABLE profesores
ADD INDEX fk_profesores_tipos_documento_idx (id_tipo_documento);

--
-- Create foreign key
--
ALTER TABLE profesores
ADD CONSTRAINT fk_profesores_tipos_documento FOREIGN KEY (id_tipo_documento)
REFERENCES tipos_documento (id_tipo_documento) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_profesores_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_profesor,
    id_tipo_documento,
    numero_documento,
    nombres,
    apellidos,
    email,
    telefono,
    especialidad
  FROM profesores
  WHERE id_profesor = p_id;
END
$$

--
-- Create procedure `sp_profesores_listar_simple`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_listar_simple ()
BEGIN
  SELECT
    id_profesor,
    CONCAT(apellidos, ', ', nombres) AS nombre_completo
  FROM profesores
  ORDER BY apellidos;
END
$$

--
-- Create procedure `sp_profesores_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_listar ()
BEGIN
  SELECT
    p.id_profesor,
    p.nombres,
    p.apellidos,
    p.email,
    p.telefono,
    p.especialidad,
    td.descripcion AS tipo_documento,
    p.numero_documento
  FROM profesores p
    JOIN tipos_documento td
      ON p.id_tipo_documento = td.id_tipo_documento
  ORDER BY p.apellidos, p.nombres;
END
$$

--
-- Create procedure `sp_profesores_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_eliminar (IN p_id int)
BEGIN
  -- Se podría añadir lógica para verificar dependencias antes de eliminar
  DELETE
    FROM profesores
  WHERE id_profesor = p_id;
END
$$

--
-- Create procedure `sp_profesores_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_crear (IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_especialidad varchar(255))
BEGIN
  INSERT INTO profesores (id_tipo_documento, numero_documento, nombres, apellidos, email, telefono, especialidad)
    VALUES (p_id_tipo_documento, p_numero_documento, p_nombres, p_apellidos, p_email, p_telefono, p_especialidad);
END
$$

--
-- Create procedure `sp_profesores_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_buscar (IN p_termino varchar(100))
BEGIN
  SELECT
    id_profesor,
    CONCAT(nombres, ' ', apellidos) AS nombre_completo
  FROM profesores
  WHERE CONCAT(nombres, ' ', apellidos) LIKE CONCAT('%', p_termino, '%')
  ORDER BY apellidos, nombres
  LIMIT 10;
END
$$

--
-- Create procedure `sp_profesores_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_actualizar (IN p_id_profesor int,
IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_especialidad varchar(255))
BEGIN
  UPDATE profesores
  SET id_tipo_documento = p_id_tipo_documento,
      numero_documento = p_numero_documento,
      nombres = p_nombres,
      apellidos = p_apellidos,
      email = p_email,
      telefono = p_telefono,
      especialidad = p_especialidad
  WHERE id_profesor = p_id_profesor;
END
$$

DELIMITER ;

