--
-- Create table `matriculas`
--
CREATE TABLE matriculas (
  id_matricula int(11) NOT NULL AUTO_INCREMENT,
  id_cliente int(11) NOT NULL,
  id_usuario_registro int(11) NOT NULL,
  id_forma_pago int(11) NOT NULL,
  fecha_matricula timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  fecha_inicio_clases date NOT NULL,
  fecha_fin_clases date NOT NULL,
  monto_total decimal(10, 2) NOT NULL,
  descuento_total decimal(10, 2) NOT NULL DEFAULT 0.00,
  monto_final decimal(10, 2) NOT NULL,
  observaciones text DEFAULT NULL,
  estado enum ('Activa', 'Completada', 'Anulada') NOT NULL DEFAULT 'Activa',
  PRIMARY KEY (id_matricula)
)
ENGINE = INNODB,
AUTO_INCREMENT = 7,
AVG_ROW_LENGTH = 16384,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `fk_matriculas_cliente_idx` on table `matriculas`
--
ALTER TABLE matriculas
ADD INDEX fk_matriculas_cliente_idx (id_cliente);

--
-- Create index `fk_matriculas_usuario_idx` on table `matriculas`
--
ALTER TABLE matriculas
ADD INDEX fk_matriculas_usuario_idx (id_usuario_registro);

--
-- Create index `fk_matriculas_forma_pago_idx` on table `matriculas`
--
ALTER TABLE matriculas
ADD INDEX fk_matriculas_forma_pago_idx (id_forma_pago);

--
-- Create foreign key
--
ALTER TABLE matriculas
ADD CONSTRAINT fk_matriculas_cliente FOREIGN KEY (id_cliente)
REFERENCES clientes (id_cliente);

--
-- Create foreign key
--
ALTER TABLE matriculas
ADD CONSTRAINT fk_matriculas_forma_pago FOREIGN KEY (id_forma_pago)
REFERENCES formas_pago (id_forma_pago);

--
-- Create foreign key
--
ALTER TABLE matriculas
ADD CONSTRAINT fk_matriculas_usuario FOREIGN KEY (id_usuario_registro)
REFERENCES usuarios (id_usuario);

DELIMITER $$

--
-- Create procedure `sp_matriculas_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matriculas_listar ()
BEGIN
  SELECT
    m.id_matricula,
    CONCAT(c.nombres, ' ', c.apellidos) AS nombre_cliente,
    m.fecha_matricula,
    m.monto_final,
    m.estado,
    u.nombre_usuario AS registrado_por
  FROM matriculas m
    JOIN clientes c
      ON m.id_cliente = c.id_cliente
    JOIN usuarios u
      ON m.id_usuario_registro = u.id_usuario
  ORDER BY m.fecha_matricula DESC;
END
$$

--
-- Create procedure `sp_matricula_registrar_cabecera`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_registrar_cabecera (IN p_id_cliente int,
IN p_id_usuario_registro int,
IN p_id_forma_pago int,
IN p_fecha_inicio_clases date,
IN p_fecha_fin_clases date,
IN p_monto_total decimal(10, 2),
IN p_descuento_total decimal(10, 2),
IN p_monto_final decimal(10, 2),
IN p_observaciones text)
BEGIN
  INSERT INTO matriculas (id_cliente, id_usuario_registro, id_forma_pago, fecha_inicio_clases, fecha_fin_clases, monto_total, descuento_total, monto_final, observaciones)
    VALUES (p_id_cliente, p_id_usuario_registro, p_id_forma_pago, p_fecha_inicio_clases, p_fecha_fin_clases, p_monto_total, p_descuento_total, p_monto_final, p_observaciones);
  SELECT
    LAST_INSERT_ID() AS id_matricula;
END
$$

--
-- Create procedure `sp_matricula_obtener_cabecera_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_obtener_cabecera_por_id (IN p_id_matricula int)
BEGIN
  SELECT
    mc.id_matricula,
    mc.id_cliente,
    CONCAT(c.nombres, ' ', c.apellidos) AS nombre_cliente,
    mc.fecha_matricula,
    mc.monto_total,
    mc.descuento_total,
    mc.monto_final,
    mc.observaciones,
    fp.nombre AS forma_pago,
    mc.estado
  FROM matriculas mc
    JOIN clientes c
      ON mc.id_cliente = c.id_cliente
    JOIN formas_pago fp
      ON mc.id_forma_pago = fp.id_forma_pago
  WHERE mc.id_matricula = p_id_matricula;
END
$$

--
-- Create procedure `sp_matricula_cabecera_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_cabecera_actualizar (IN p_id_matricula int,
IN p_id_forma_pago int,
IN p_observaciones text)
BEGIN
  UPDATE matriculas
  SET id_forma_pago = p_id_forma_pago,
      observaciones = p_observaciones
  WHERE id_matricula = p_id_matricula;
END
$$

