DELIMITER $$

--
-- Create procedure `sp_sub_areas_validar_capacidad`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_sub_areas_validar_capacidad (IN p_id_sub_area int,
IN p_capacidad_maxima int)
BEGIN
  DECLARE v_inscritos int;
  DECLARE v_id_curso_programado int;
  DECLARE v_nombre_curso varchar(150);
  DECLARE v_error_message varchar(255) DEFAULT NULL;
  DECLARE done int DEFAULT FALSE;

  -- Cursor para iterar sobre los cursos afectados
  DECLARE cur_cursos_afectados CURSOR FOR
  SELECT
    cp.id_curso_programado,
    c.nombre
  FROM cursos_programados cp
    JOIN cursos c
      ON cp.id_curso = c.id_curso
  WHERE cp.id_sub_area = p_id_sub_area
  AND cp.estado IN ('Programado', 'En Curso');

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  -- Bucle de validación
  OPEN cur_cursos_afectados;
validation_loop:
  LOOP
    FETCH cur_cursos_afectados INTO v_id_curso_programado, v_nombre_curso;
    IF done THEN
      LEAVE validation_loop;
    END IF;

    -- Contar inscritos para este curso
    SELECT
      COUNT(*) INTO v_inscritos
    FROM matriculas_detalle md
      JOIN matriculas m
        ON md.id_matricula = m.id_matricula
    WHERE md.id_curso_programado = v_id_curso_programado
    AND m.estado = 'Activa';

    -- Si la nueva capacidad es insuficiente, preparar mensaje de error y salir
    IF p_capacidad_maxima < v_inscritos THEN
      SET v_error_message = CONCAT('No se puede reducir la capacidad a ', p_capacidad_maxima, '. El curso "', v_nombre_curso, '" ya tiene ', v_inscritos, ' alumnos inscritos.');
      LEAVE validation_loop;
    END IF;
  END LOOP;
  CLOSE cur_cursos_afectados;

  -- Devolver el mensaje de error si existe
  IF v_error_message IS NOT NULL THEN
    SELECT
      v_error_message AS error;
  END IF;

END
$$

--
-- Create procedure `sp_sub_areas_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_sub_areas_actualizar (IN p_id_sub_area int,
IN p_id_area int,
IN p_descripcion varchar(100),
IN p_numero_sub_area varchar(20),
IN p_capacidad_maxima int)
BEGIN
  DECLARE v_inscritos int;
  DECLARE v_id_curso_programado int;
  DECLARE v_nombre_curso varchar(150);
  DECLARE v_error_message varchar(255);
  DECLARE done int DEFAULT FALSE;

  -- Cursor para iterar sobre los cursos afectados
  DECLARE cur_cursos_afectados CURSOR FOR
  SELECT
    cp.id_curso_programado,
    c.nombre
  FROM cursos_programados cp
    JOIN cursos c
      ON cp.id_curso = c.id_curso
  WHERE cp.id_sub_area = p_id_sub_area
  AND cp.estado IN ('Programado', 'En Curso'); -- Solo considerar cursos activos o futuros

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  START TRANSACTION;

    -- 1. Validación: La nueva capacidad no puede ser menor a los inscritos
    OPEN cur_cursos_afectados;
  validation_loop:
    LOOP
      FETCH cur_cursos_afectados INTO v_id_curso_programado, v_nombre_curso;
      IF done THEN
        LEAVE validation_loop;
      END IF;

      -- Contar inscritos para este curso
      SELECT
        COUNT(*) INTO v_inscritos
      FROM matriculas_detalle md
        JOIN matriculas m
          ON md.id_matricula = m.id_matricula
      WHERE md.id_curso_programado = v_id_curso_programado
      AND m.estado = 'Activa';

      -- Si la nueva capacidad es insuficiente, lanzar error
      IF p_capacidad_maxima < v_inscritos THEN
        SET v_error_message = CONCAT('No se puede reducir la capacidad a ', p_capacidad_maxima, '. El curso "', v_nombre_curso, '" ya tiene ', v_inscritos, ' alumnos inscritos.');
        ROLLBACK;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_error_message;
      END IF;
    END LOOP;
    CLOSE cur_cursos_afectados;
    SET done = FALSE; -- Resetear 'done' para el próximo cursor

    -- 2. Si la validación pasa, actualizar la sub-área
    UPDATE sub_areas
    SET id_area = p_id_area,
        descripcion = p_descripcion,
        numero_sub_area = p_numero_sub_area,
        capacidad_maxima = p_capacidad_maxima
    WHERE id_sub_area = p_id_sub_area;

    -- 3. Recalcular y actualizar las vacantes de los cursos afectados
    OPEN cur_cursos_afectados;
  update_loop:
    LOOP
      FETCH cur_cursos_afectados INTO v_id_curso_programado, v_nombre_curso;
      IF done THEN
        LEAVE update_loop;
      END IF;

      -- Contar inscritos de nuevo (para estar seguros)
      SELECT
        COUNT(*) INTO v_inscritos
      FROM matriculas_detalle md
        JOIN matriculas m
          ON md.id_matricula = m.id_matricula
      WHERE md.id_curso_programado = v_id_curso_programado
      AND m.estado = 'Activa';

      -- Actualizar vacantes disponibles
      UPDATE cursos_programados
      SET vacantes_disponibles = p_capacidad_maxima - v_inscritos
      WHERE id_curso_programado = v_id_curso_programado;
    END LOOP;
    CLOSE cur_cursos_afectados;

  COMMIT;
END
$$

--
-- Create procedure `sp_matriculas_contar_por_curso`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matriculas_contar_por_curso (IN p_id_curso_programado int)
BEGIN
  SELECT
    COUNT(md.id_matricula_detalle) AS inscritos
  FROM matriculas_detalle md
    JOIN matriculas mc
      ON md.id_matricula = mc.id_matricula
  WHERE md.id_curso_programado = p_id_curso_programado
  AND mc.estado = 'Activa'; -- Contar solo matrículas activas
END
$$

--
-- Create procedure `sp_matricula_registrar_detalle`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_registrar_detalle (IN p_id_matricula int,
IN p_id_curso_programado int,
IN p_id_cliente_asistencia int, -- Nuevo parámetro
IN p_precio_pactado decimal(10, 2),
IN p_descuento decimal(10, 2),
IN p_precio_final decimal(10, 2))
BEGIN
  DECLARE v_vacantes int;
  -- Verificar vacantes
  SELECT
    vacantes_disponibles INTO v_vacantes
  FROM cursos_programados
  WHERE id_curso_programado = p_id_curso_programado;
  IF v_vacantes > 0 THEN
    -- Insertar detalle
    INSERT INTO matriculas_detalle (id_matricula, id_curso_programado, id_cliente_asistencia, precio_pactado, descuento, precio_final)
      VALUES (p_id_matricula, p_id_curso_programado, p_id_cliente_asistencia, p_precio_pactado, p_descuento, p_precio_final);
    -- Actualizar vacantes
    UPDATE cursos_programados
    SET vacantes_disponibles = vacantes_disponibles - 1
    WHERE id_curso_programado = p_id_curso_programado;
    SELECT
      LAST_INSERT_ID() AS id_matricula_detalle;
  ELSE
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay vacantes disponibles para este curso.';
  END IF;
END
$$

--
-- Create procedure `sp_matricula_obtener_detalles_por_id_matricula`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_obtener_detalles_por_id_matricula (IN p_id_matricula int)
BEGIN
  SELECT
    md.id_matricula_detalle,
    md.id_curso_programado,
    cur.nombre AS nombre_curso,
    md.id_cliente_asistencia,
    CONCAT(cli_asist.nombres, ' ', cli_asist.apellidos) AS nombre_cliente_asistencia,
    md.precio_pactado,
    md.descuento,
    md.precio_final,
    -- Campos adicionales para la vista de edición
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS ubicacion,
    CONCAT(p.nombres, ' ', p.apellidos) AS profesor,
    th.descripcion AS horario_dias,
    cp.hora_inicio,
    cp.hora_fin,
    th.dias_semana,
    cp.fecha_inicio,
    cp.fecha_fin
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos cur
      ON cp.id_curso = cur.id_curso
    JOIN clientes cli_asist
      ON md.id_cliente_asistencia = cli_asist.id_cliente
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_matricula = p_id_matricula
  ORDER BY md.id_matricula_detalle ASC;
END
$$

--
-- Create procedure `sp_matricula_cabecera_recalcular`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_cabecera_recalcular (IN p_id_matricula int)
BEGIN
  DECLARE v_monto_total decimal(10, 2);
  DECLARE v_descuento_total decimal(10, 2);
  DECLARE v_monto_final decimal(10, 2);

  SELECT
    IFNULL(SUM(precio_pactado), 0),
    IFNULL(SUM(descuento), 0) INTO v_monto_total, v_descuento_total
  FROM matriculas_detalle
  WHERE id_matricula = p_id_matricula;

  SET v_monto_final = v_monto_total - v_descuento_total;

  UPDATE matriculas
  SET monto_total = v_monto_total,
      descuento_total = v_descuento_total,
      monto_final = v_monto_final
  WHERE id_matricula = p_id_matricula;
END
$$

--
-- Create procedure `sp_dashboard_ventas_por_sub_area`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_ventas_por_sub_area (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS `label`,
    SUM(md.precio_final) AS `total_ventas`
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  AND m.estado = 'Activa'
  GROUP BY `label`
  ORDER BY `total_ventas` DESC;
END
$$

--
-- Create procedure `sp_dashboard_ventas_por_profesor`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_ventas_por_profesor (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    CONCAT(p.nombres, ' ', p.apellidos) AS `nombre_profesor`,
    SUM(md.precio_final) AS `total_ventas`
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  AND m.estado = 'Activa'
  GROUP BY p.id_profesor,
           nombre_profesor
  ORDER BY total_ventas DESC,
  nombre_profesor ASC;
END
$$

--
-- Create procedure `sp_dashboard_ventas_por_curso`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_ventas_por_curso (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    c.nombre AS nombre_curso,
    SUM(md.precio_final) AS total_ventas
  FROM matriculas_detalle md
    JOIN matriculas m
      ON md.id_matricula = m.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos c
      ON cp.id_curso = c.id_curso
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  GROUP BY c.nombre
  ORDER BY total_ventas DESC;
END
$$

--
-- Create procedure `sp_dashboard_ventas_mes_por_curso_area`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_ventas_mes_por_curso_area (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    CONCAT(c.nombre, ' (', a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area, ')') AS `label`,
    SUM(md.precio_final) AS `total_ventas`
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  AND m.estado = 'Activa' -- o considerar también 'Completada'
  GROUP BY `label`
  ORDER BY `total_ventas` DESC;
END
$$

--
-- Create procedure `sp_dashboard_ventas_anuales_por_mes_y_curso`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_ventas_anuales_por_mes_y_curso (IN p_anio int)
BEGIN
  SELECT
    MONTH(m.fecha_matricula) AS `mes`,
    c.nombre AS `nombre_curso`,
    SUM(md.precio_final) AS `total_ventas`
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos c
      ON cp.id_curso = c.id_curso
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND m.estado = 'Activa'
  GROUP BY `mes`,
           `nombre_curso`
  ORDER BY `mes`,
  `nombre_curso`;
END
$$

--
-- Create procedure `sp_dashboard_matriculados_por_sub_area`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_dashboard_matriculados_por_sub_area (IN p_anio int,
IN p_mes int)
BEGIN
  SELECT
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS `label`,
    COUNT(md.id_matricula_detalle) AS `cantidad_matriculados`
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE YEAR(m.fecha_matricula) = p_anio
  AND MONTH(m.fecha_matricula) = p_mes
  AND m.estado = 'Activa'
  GROUP BY `label`
  ORDER BY `cantidad_matriculados` DESC;
END
$$

--
-- Create procedure `sp_cliente_horarios_activos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cliente_horarios_activos (IN p_id_cliente int)
BEGIN
  SELECT
    cp.id_sub_area,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin,
    th.dias_semana
  FROM matriculas m
    JOIN matriculas_detalle md
      ON m.id_matricula = md.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_cliente_asistencia = p_id_cliente
  AND m.estado = 'Activa';
END
$$

--
-- Create procedure `sp_calendario_cursos_activos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_calendario_cursos_activos ()
BEGIN
  SELECT
    m.id_matricula,
    md.id_matricula_detalle,
    cp.id_curso_programado,
    c.id_curso,
    c.nombre AS nombre_curso,
    a.id_area,
    a.nombre AS nombre_area,
    sa.id_sub_area,
    sa.descripcion AS nombre_sub_area,
    sa.numero_sub_area,
    CONCAT(p.nombres, ' ', p.apellidos) AS nombre_profesor,
    cli.id_cliente,
    CONCAT(cli.nombres, ' ', cli.apellidos) AS nombre_cliente,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin,
    th.descripcion AS horario_dias,
    th.dias_semana -- Formato '1,3,5' para L,M,V
  FROM matriculas_detalle md
    JOIN matriculas m
      ON md.id_matricula = m.id_matricula
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN clientes cli
      ON md.id_cliente_asistencia = cli.id_cliente
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE m.estado = 'Activa';
END
$$

--
-- Create procedure `sp_asistencia_cliente_obtener_detalle_curso`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_obtener_detalle_curso (IN p_id_matricula_detalle int)
BEGIN
  SELECT
    c.nombre AS curso_nombre,
    CONCAT(cli.nombres, ' ', cli.apellidos) AS cliente_nombre,
    CONCAT(p.nombres, ' ', p.apellidos) AS profesor_nombre,
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS ubicacion,
    th.descripcion AS tipo_horario_nombre,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN clientes cli
      ON md.id_cliente_asistencia = cli.id_cliente
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_matricula_detalle = p_id_matricula_detalle;
END
$$

--
-- Create procedure `sp_asistencia_cliente_listar_cursos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_listar_cursos (IN p_id_cliente int,
IN p_id_curso int,
IN p_fecha_inicio date,
IN p_fecha_fin date)
BEGIN
  SELECT
    mc.id_matricula,
    md.id_matricula_detalle,
    cp.id_curso_programado,
    c.nombre AS curso_nombre,
    CONCAT(cli.nombres, ' ', cli.apellidos) AS cliente_nombre,
    cp.fecha_inicio,
    cp.fecha_fin,
    th.descripcion AS dias,
    CONCAT(TIME_FORMAT(cp.hora_inicio, '%h:%i %p'), ' - ', TIME_FORMAT(cp.hora_fin, '%h:%i %p')) AS horas,
    CONCAT(a.nombre, ' - ', sa.descripcion, ' ', sa.numero_sub_area) AS ubicacion,
    mc.estado
  FROM matriculas mc
    JOIN matriculas_detalle md
      ON mc.id_matricula = md.id_matricula
    JOIN clientes cli
      ON md.id_cliente_asistencia = cli.id_cliente
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
  WHERE (p_id_cliente IS NULL
  OR md.id_cliente_asistencia = p_id_cliente)
  AND (p_id_curso IS NULL
  OR cp.id_curso = p_id_curso)
  AND (p_fecha_inicio IS NULL
  OR cp.fecha_inicio >= p_fecha_inicio)
  AND (p_fecha_fin IS NULL
  OR cp.fecha_fin <= p_fecha_fin)
  ORDER BY cp.fecha_inicio DESC, cliente_nombre ASC;
END
$$

DELIMITER ;

--
-- Create table `asistencia_cliente`
--
CREATE TABLE asistencia_cliente (
  id_asistencia_cliente int(11) NOT NULL AUTO_INCREMENT,
  id_matricula_detalle int(11) NOT NULL,
  id_cliente int(11) NOT NULL,
  fecha_clase date NOT NULL,
  estado enum ('Programado', 'Asistió', 'Faltó', 'Justificado', 'Postergado') NOT NULL DEFAULT 'Programado',
  observaciones varchar(255) DEFAULT NULL,
  PRIMARY KEY (id_asistencia_cliente)
)
ENGINE = INNODB,
AUTO_INCREMENT = 134,
AVG_ROW_LENGTH = 910,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `fk_asist_cli_matricula_det_idx` on table `asistencia_cliente`
--
ALTER TABLE asistencia_cliente
ADD INDEX fk_asist_cli_matricula_det_idx (id_matricula_detalle);

--
-- Create index `fk_asist_cli_cliente_idx` on table `asistencia_cliente`
--
ALTER TABLE asistencia_cliente
ADD INDEX fk_asist_cli_cliente_idx (id_cliente);

--
-- Create foreign key
--
ALTER TABLE asistencia_cliente
ADD CONSTRAINT fk_asist_cli_cliente FOREIGN KEY (id_cliente)
REFERENCES clientes (id_cliente);

--
-- Create foreign key
--
ALTER TABLE asistencia_cliente
ADD CONSTRAINT fk_asist_cli_matricula_det FOREIGN KEY (id_matricula_detalle)
REFERENCES matriculas_detalle (id_matricula_detalle);

DELIMITER $$

--
-- Create procedure `sp_matricula_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_eliminar (IN p_id_matricula int)
BEGIN
  DECLARE done int DEFAULT FALSE;
  DECLARE cur_id_curso_programado int;
  DECLARE cur_id_matricula_detalle int;

  -- Cursor para iterar sobre los detalles de la matrícula a eliminar
  DECLARE cur_detalles CURSOR FOR
  SELECT
    id_matricula_detalle,
    id_curso_programado
  FROM matriculas_detalle
  WHERE id_matricula = p_id_matricula;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  START TRANSACTION;

    -- 1. Devolver las vacantes de cada curso en la matrícula
    OPEN cur_detalles;
  devolver_loop:
    LOOP
      FETCH cur_detalles INTO cur_id_matricula_detalle, cur_id_curso_programado;
      IF done THEN
        LEAVE devolver_loop;
      END IF;
      -- Incrementar la vacante
      UPDATE cursos_programados
      SET vacantes_disponibles = vacantes_disponibles + 1
      WHERE id_curso_programado = cur_id_curso_programado;
    END LOOP;
    CLOSE cur_detalles;

    -- 2. Eliminar los registros de asistencia asociados
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle IN (SELECT
          id_matricula_detalle
        FROM matriculas_detalle
        WHERE id_matricula = p_id_matricula);

    -- 3. Eliminar los registros de detalle
    DELETE
      FROM matriculas_detalle
    WHERE id_matricula = p_id_matricula;

    -- 4. Eliminar la cabecera
    DELETE
      FROM matriculas
    WHERE id_matricula = p_id_matricula;

  COMMIT;
END
$$

--
-- Create procedure `sp_matricula_detalle_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_detalle_eliminar (IN p_id_matricula_detalle int)
BEGIN
  DECLARE v_id_curso_programado int;

  -- Obtener el curso programado antes de eliminar
  SELECT
    id_curso_programado INTO v_id_curso_programado
  FROM matriculas_detalle
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Si encontramos el detalle, proceder
  IF v_id_curso_programado IS NOT NULL THEN
    -- 1. Devolver la vacante al curso
    UPDATE cursos_programados
    SET vacantes_disponibles = vacantes_disponibles + 1
    WHERE id_curso_programado = v_id_curso_programado;

    -- 2. Eliminar la asistencia generada
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle = p_id_matricula_detalle;

    -- 3. Eliminar el detalle de la matrícula
    DELETE
      FROM matriculas_detalle
    WHERE id_matricula_detalle = p_id_matricula_detalle;
  END IF;
END
$$

--
-- Create procedure `sp_matricula_anular`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_anular (IN p_id_matricula int,
IN p_observaciones text)
BEGIN
  DECLARE v_estado_actual varchar(20);

  -- Iniciar transacción
  START TRANSACTION;

    -- Verificar que la matrícula no esté ya anulada
    SELECT
      estado INTO v_estado_actual
    FROM matriculas
    WHERE id_matricula = p_id_matricula;

    IF v_estado_actual = 'Activa' THEN
      -- 1. Actualizar el estado de la matrícula y añadir la observación
      UPDATE matriculas
      SET estado = 'Anulada',
          observaciones = CONCAT(IFNULL(observaciones, ''), '\nANULACIÓN: ', p_observaciones)
      WHERE id_matricula = p_id_matricula;

      -- 2. Devolver las vacantes de los cursos asociados a esta matrícula
      UPDATE cursos_programados cp
      JOIN matriculas_detalle md
        ON cp.id_curso_programado = md.id_curso_programado
      SET cp.vacantes_disponibles = cp.vacantes_disponibles + 1
      WHERE md.id_matricula = p_id_matricula;

      -- 3. Opcional: Cambiar el estado de la asistencia del cliente a 'Cancelado'
      UPDATE asistencia_cliente ac
      JOIN matriculas_detalle md
        ON ac.id_matricula_detalle = md.id_matricula_detalle
      SET ac.estado = 'Cancelado'
      WHERE md.id_matricula = p_id_matricula;

      COMMIT;
    ELSE
      -- Si ya está anulada o completada, no hacer nada y revertir
      ROLLBACK;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La matrícula no se puede anular porque no está activa.';
    END IF;
END
$$

--
-- Create procedure `sp_asistencia_cliente_obtener_clases`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_obtener_clases (IN p_id_matricula_detalle int,
IN p_limit int,
IN p_offset int)
BEGIN
  SELECT
    id_asistencia_cliente,
    fecha_clase,
    estado,
    observaciones
  FROM asistencia_cliente
  WHERE id_matricula_detalle = p_id_matricula_detalle
  ORDER BY fecha_clase ASC
  LIMIT p_limit OFFSET p_offset;
END
$$

--
-- Create procedure `sp_asistencia_cliente_generar_cronograma`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_generar_cronograma (IN p_id_matricula_detalle int)
BEGIN
  DECLARE v_fecha_actual date;
  DECLARE v_fecha_fin date;
  DECLARE v_id_cliente int;
  DECLARE v_id_curso_programado int;
  DECLARE v_dias_semana varchar(20);

  -- Obtener datos de la programación y el cliente de asistencia
  SELECT
    cp.fecha_inicio,
    cp.fecha_fin,
    md.id_cliente_asistencia,
    cp.id_curso_programado,
    th.dias_semana INTO v_fecha_actual, v_fecha_fin, v_id_cliente, v_id_curso_programado, v_dias_semana
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_matricula_detalle = p_id_matricula_detalle;

  -- Solo generar si hay un cliente de asistencia asignado
  IF v_id_cliente IS NOT NULL THEN
    -- Limpiar cronograma existente por si se regenera
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle = p_id_matricula_detalle;

    -- Bucle para generar registros de asistencia
    WHILE v_fecha_actual <= v_fecha_fin DO
      IF FIND_IN_SET(WEEKDAY(v_fecha_actual) + 1, v_dias_semana COLLATE utf8mb4_unicode_ci) THEN
        INSERT INTO asistencia_cliente (id_matricula_detalle, id_cliente, fecha_clase, estado)
          VALUES (p_id_matricula_detalle, v_id_cliente, v_fecha_actual, 'Programado');
      END IF;
      SET v_fecha_actual = DATE_ADD(v_fecha_actual, INTERVAL 1 DAY);
    END WHILE;
  END IF;
END
$$

--
-- Create procedure `sp_matricula_detalle_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_detalle_actualizar (IN p_id_matricula_detalle int,
IN p_id_cliente_asistencia int,
IN p_precio_pactado decimal(10, 2),
IN p_descuento decimal(10, 2))
BEGIN
  DECLARE v_precio_final decimal(10, 2);
  DECLARE v_cliente_actual int;

  -- Obtener el cliente de asistencia actual para comparar
  SELECT
    id_cliente_asistencia INTO v_cliente_actual
  FROM matriculas_detalle
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Calcular el nuevo precio final
  SET v_precio_final = p_precio_pactado - p_descuento;

  -- Actualizar el registro de detalle
  UPDATE matriculas_detalle
  SET id_cliente_asistencia = p_id_cliente_asistencia,
      precio_pactado = p_precio_pactado,
      descuento = p_descuento,
      precio_final = v_precio_final
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Si el cliente de asistencia ha cambiado, se debe regenerar el cronograma
  IF v_cliente_actual != p_id_cliente_asistencia THEN
    CALL sp_asistencia_cliente_generar_cronograma(p_id_matricula_detalle);
  END IF;
END
$$

