--
-- Create procedure `sp_asistencia_cliente_agregar_dias`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_agregar_dias (IN p_id_matricula_detalle int,
IN p_fecha_fin date)
BEGIN
  DECLARE v_fecha date;
  DECLARE v_fecha_fin_curso date;
  DECLARE v_id_cliente int;
  DECLARE v_dias_semana varchar(20);
  DECLARE v_dias_agregados int DEFAULT 0;

  SELECT
    cp.fecha_inicio,
    cp.fecha_fin,
    md.id_cliente_asistencia,
    th.dias_semana INTO v_fecha, v_fecha_fin_curso, v_id_cliente, v_dias_semana
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON cp.id_curso_programado = md.id_curso_programado
    JOIN tipos_horario th
      ON th.id_tipo_horario = cp.id_tipo_horario
  WHERE md.id_matricula_detalle = p_id_matricula_detalle;

  IF v_id_cliente IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Detalle de matr├¡cula no encontrado.';
  END IF;

  IF p_fecha_fin < v_fecha THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha final debe ser igual o posterior al inicio del curso.';
  END IF;

  WHILE v_fecha <= p_fecha_fin DO
    IF FIND_IN_SET(WEEKDAY(v_fecha) + 1, v_dias_semana) > 0
      AND NOT EXISTS (SELECT
          1
        FROM asistencia_cliente
        WHERE id_matricula_detalle = p_id_matricula_detalle
        AND fecha_clase = v_fecha) THEN
      INSERT INTO asistencia_cliente (id_matricula_detalle, id_cliente, fecha_clase, estado, observaciones)
        VALUES
        (p_id_matricula_detalle, v_id_cliente, v_fecha, 'Programado', NULL);
      SET v_dias_agregados = v_dias_agregados + 1;
    END IF;
    SET v_fecha = DATE_ADD(v_fecha, INTERVAL 1 DAY);
  END WHILE;

  SELECT
    v_dias_agregados AS dias_agregados;
END
$$

