DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    lp.id_lista_precio,
    c.nombre AS curso_nombre,
    tp.nombre AS tipo_precio_nombre,
    lp.precio,
    lp.vigencia_inicio,
    lp.vigencia_fin
  FROM lista_precios lp
    JOIN cursos c
      ON lp.id_curso = c.id_curso
    JOIN tipos_precio tp
      ON lp.id_tipo_precio = tp.id_tipo_precio
  WHERE c.nombre LIKE CONCAT('%', p_term, '%')
  OR tp.nombre LIKE CONCAT('%', p_term, '%')
